<?php require __DIR__.'/../bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('/admin/media/');verify_csrf();$id=(int)post('id');$s=db()->prepare('SELECT * FROM media_assets WHERE id=? AND kind=\'archive\'');$s->execute([$id]);$m=$s->fetch();if(!$m||!$m['storage_path']){flash('error','Archive not found.');redirect('/admin/media/');}$path=__DIR__.'/..'.$m['storage_path'];if(!class_exists('ZipArchive')){flash('error','ZipArchive is not enabled on this hosting.');redirect('/admin/media-archive/?id='.$id);}$zip=new ZipArchive();if($zip->open($path)!==true){flash('error','Could not open archive.');redirect('/admin/media-archive/?id='.$id);}$dir=__DIR__.'/../uploads/media/extracted/'.bin2hex(random_bytes(8));mkdir($dir,0750,true);$ok=$zip->extractTo($dir);$zip->close();if(!$ok){flash('error','Archive extraction failed.');redirect('/admin/media-archive/?id='.$id);}flash('success','Archive extracted to the media storage.');redirect('/admin/media/');